/* HEXA BATTLEGROUNDS setup — PART 8 OF 19. Run parts in order. Safe to re-run. */ create or replace function host_settings(p_token text, p_settings jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; k text; begin v_ev := _auth_host(p_token); for k in select jsonb_object_keys(p_settings) loop if not (_defaults() ? k) then raise exception 'UNKNOWN_SETTING: %', k; end if; end loop; update events set settings = settings || p_settings where id = v_ev; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'settings', p_settings); return (select _defaults() || settings from events where id = v_ev); end $$; create or replace function host_missions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ begin perform _auth_host(p_token); return (select coalesce(jsonb_agg(to_jsonb(m) order by m.kind, m.id), '[]'::jsonb) from mission_templates m); end $$; create or replace function host_save_mission(p_token text, p_mission jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; m jsonb := p_mission; v_parts jsonb; v_role text; begin v_ev := _auth_host(p_token); if coalesce(m ->> 'id', '') !~ '^[a-z0-9_-]{3,60}$' then raise exception 'BAD_ID'; end if; foreach v_role in array array['scout', 'decoder', 'intel'] loop if coalesce(m -> 'clues' -> v_role ->> 'body', '') = '' then raise exception 'MISSING_CLUE: %', v_role; end if; end loop; select jsonb_agg(jsonb_build_object('label', coalesce(pt ->> 'label', 'Answer'), 'accept', (select jsonb_agg(case when acc = '{KEY}' then acc else _norm(acc) end) from jsonb_array_elements_text(pt -> 'accept') acc))) into v_parts from jsonb_array_elements(m -> 'parts') pt; if v_parts is null or exists (select 1 from jsonb_array_elements(v_parts) pt where jsonb_array_length(coalesce(pt -> 'accept', '[]')) = 0 or exists (select 1 from jsonb_array_elements_text(pt -> 'accept') acc where acc = '')) then raise exception 'MISSING_ANSWER'; end if; insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values (m ->> 'id', coalesce(m ->> 'family', 'custom'), coalesce(m ->> 'kind', 'mission'), m ->> 'title', coalesce(m ->> 'category', 'custom'), coalesce((m ->> 'difficulty')::int, 1), coalesce((select array_agg(x) from jsonb_array_elements_text(m -> 'tags') x), array['any']), m ->> 'objective', m -> 'clues', v_parts, coalesce((m ->> 'relay')::boolean, false), coalesce((m ->> 'attempts')::int, 3), coalesce((m ->> 'time_limit')::int, 180), m ->> 'hint', m ->> 'explanation', nullif(m ->> 'points', '')::int, coalesce((m ->> 'coins')::int, 25), coalesce(m ->> 'status', 'draft')) on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = mission_templates.version + 1, updated_at = now(); insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'save_mission', jsonb_build_object('id', m ->> 'id', 'status', m ->> 'status')); return (select to_jsonb(mt) from mission_templates mt where id = m ->> 'id'); end $$; create or replace function host_test_answer(p_token text, p_template text, p_answers jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare mt mission_templates; v_part jsonb; v_i int := 0; v_ok boolean := true; begin perform _auth_host(p_token); select * into mt from mission_templates where id = p_template; if mt.id is null then raise exception 'NOT_FOUND'; end if; for v_part in select value from jsonb_array_elements(mt.parts) loop if not exists (select 1 from jsonb_array_elements_text(v_part -> 'accept') acc where acc = '{KEY}' or acc = _norm(p_answers ->> v_i)) then v_ok := false; end if; v_i := v_i + 1; end loop; return jsonb_build_object('correct', v_ok); end $$; create or replace function host_chat_log(p_token text, p_arena uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'from', (select number from teams where id = c.from_team), 'to', (select number from teams where id = c.to_team), 'body', c.body, 'at', c.at, 'hidden', c.hidden, 'reported', c.reported) order by c.id desc), '[]'::jsonb) from (select * from chat_messages where arena_id = p_arena and arena_id in (select id from arenas where event_id = v_ev) order by id desc limit 200) c); end $$; create or replace function host_audit(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return jsonb_build_object( 'audit', (select coalesce(jsonb_agg(to_jsonb(x) order by x.id desc), '[]'::jsonb) from (select * from audit_log where event_id = v_ev order by id desc limit 200) x), 'ledger', (select coalesce(jsonb_agg(jsonb_build_object('at', l.at, 'team', t.number, 'kind', l.kind, 'points', l.points, 'coins', l.coins, 'hp', l.hp, 'trust', l.trust, 'reason', l.reason, 'actor', l.actor) order by l.id desc), '[]'::jsonb) from (select * from ledger where arena_id in (select id from arenas where event_id = v_ev) order by id desc limit 300) l join teams t on t.id = l.team_id)); end $$; create or replace function host_export(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return jsonb_build_object( 'event', (select jsonb_build_object('code', code, 'name', name, 'settings', _defaults() || settings) from events where id = v_ev), 'grand_standings', _event_standings(v_ev), 'arenas', (select jsonb_agg(jsonb_build_object('number', number, 'name', name, 'standings', _standings(id), 'threat', threat) order by number) from arenas where event_id = v_ev), 'ledger', (select coalesce(jsonb_agg(jsonb_build_object('at', l.at, 'team', t.number, 'kind', l.kind, 'points', l.points, 'coins', l.coins, 'hp', l.hp, 'trust', l.trust, 'reason', l.reason, 'actor', l.actor) order by l.id), '[]'::jsonb) from ledger l join teams t on t.id = l.team_id where t.event_id = v_ev), 'audit', (select coalesce(jsonb_agg(to_jsonb(x) order by x.id), '[]'::jsonb) from audit_log x where x.event_id = v_ev), 'aggregates', jsonb_build_object( 'missions_solved', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status = 'solved'), 'missions_failed', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status in ('failed', 'expired')), 'avg_solve_seconds', (select round(avg(extract(epoch from mi.solved_at - mi.started_at))) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status = 'solved'), 'hints_used', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.hint_used), 'battles', (select count(*) from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev), 'airdrops_claimed', (select count(*) from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'claimed'), 'messages', (select count(*) from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev), 'recoveries', (select count(*) from ledger l join teams t on t.id = l.team_id where t.event_id = v_ev and l.kind = 'recovery_penalty')) ); end $$; create or replace function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare a arenas; e events; sr sync_rounds; v_recap jsonb; v_show_scores boolean; begin select * into a from arenas where spectator_token = p_token; if a.id is null or p_token is null or length(p_token) < 16 then raise exception 'SPECTATOR_AUTH'; end if; perform _tick(a.id); select * into a from arenas where id = a.id; select * into e from events where id = a.event_id; select * into sr from sync_rounds where id = a.sync_round_id; v_show_scores := a.phase in ('lobby', 'boarding', 'shuttle', 'roles', 'play'); if a.phase in ('finale', 'results', 'ended') and coalesce(a.finale_stage, 'A') >= 'D' then v_recap := jsonb_build_object( 'bargains_accepted', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and (b ->> 'accept')::boolean), 'bargains_refused', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and not (b ->> 'accept')::boolean), 'betrayals', (select count(*) from alliances where arena_id = a.id and status = 'betrayed'), 'alliances', (select count(*) from alliances where arena_id = a.id and status in ('active', 'ended', 'expired', 'betrayed') and expires_at > created_at and status <> 'expired'), 'codewords_shared', (select count(*) from ledger where arena_id = a.id and kind = 'relay_assist'), 'battles', (select count(*) from battles where arena_id = a.id), 'threat', a.threat); end if; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('name', e.name, 'code', e.code, 'grand_revealed', e.grand_revealed), 'arena', jsonb_build_object('id', a.id, 'number', a.number, 'name', a.name, 'phase', a.phase, 'paused', a.paused, 'shuttle_departed_at', a.shuttle_departed_at, 'shuttle_arrive_at', a.shuttle_arrive_at, 'roles_deadline', a.roles_deadline, 'zone_stage', a.zone_stage, 'zone_next_at', a.zone_next_at, 'finale_stage', a.finale_stage, 'threat', a.threat, 'overlay', a.overlay, 'results_locked', a.results_locked, 'winner_revealed', a.winner_revealed), 'squads', (select coalesce(jsonb_agg(jsonb_build_object('number', t.number, 'name', t.name, 'ready', t.ready, 'bus', t.bus, 'players', (select count(*) from players where team_id = t.id and active), 'hp', t.hp, 'state', t.state, 'points', case when v_show_scores then t.points end, 'location', case when t.jammed_until is null or t.jammed_until < now() then t.location_id end, 'travel_to', case when t.jammed_until is null or t.jammed_until < now() then t.travel_to end, 'travel_from', case when t.jammed_until is null or t.jammed_until < now() then t.travel_from end, 'travel_started_at', t.travel_started_at, 'travel_arrive_at', t.travel_arrive_at, 'in_battle', exists (select 1 from battles b where b.status = 'active' and (b.attacker_id = t.id or b.defender_id = t.id)), 'sync_solved', case when sr.id is not null then exists (select 1 from mission_instances mi where mi.sync_round_id = sr.id and mi.team_id = t.id and mi.status = 'solved') end ) order by t.number), '[]'::jsonb) from teams t where t.arena_id = a.id), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('location', location_id, 'tier', tier, 'expires_at', expires_at)), '[]'::jsonb) from airdrops where arena_id = a.id and status = 'open'), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'weapon', b.weapon, 'location', b.location_id, 'deadline', b.deadline)), '[]'::jsonb) from battles b where b.arena_id = a.id and b.status = 'active'), 'sync', case when sr.id is not null then jsonb_build_object('kind', sr.kind, 'stage', sr.stage, 'deadline', sr.deadline, 'title', (select title from mission_templates where id = sr.template_id), 'solved', (select count(*) from mission_instances where sync_round_id = sr.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = sr.id)) end, 'story', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'title', title, 'body', body, 'at', at) order by at desc), '[]'::jsonb) from (select * from story_events where arena_id = a.id order by at desc limit 3) s), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'type', type, 'payload', payload, 'at', at) order by id desc), '[]'::jsonb) from (select * from game_feed where arena_id = a.id order by id desc limit 30) f), 'recap', v_recap, 'results', case when a.winner_revealed then a.results end, 'grand', case when e.grand_revealed then _event_standings(e.id) end ); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
